1	package app
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/token"
7		"sort"
8		"strconv"
9		"strings"
10		"testing"
11	
12		tea "github.com/charmbracelet/bubbletea"
13	
14		"github.com/anthnel/devdesk/internal/command"
15		"github.com/anthnel/devdesk/internal/ui/datatable"
16		"github.com/anthnel/devdesk/internal/ui/help"
17		"github.com/anthnel/devdesk/internal/ui/indicator"
18	)
19	
20	// A-16 (DEVDESK-143), skeleton delivered with the :jobs pilot (DEVDESK-142).
21	//
22	// The guard answers one question for every view the router can build: is it on
23	// the activity column, is it waiting for its migration, or is it exempt for a
24	// stated reason? A view that is none of the three fails the test by name. It
25	// is a skeleton: DEVDESK-143 completes it (footer half of criterion 5,
26	// criterion 7).
27	
28	// activityView is what a migrated view exposes to the guard: read-only tables,
29	// keyed "<view>/<table>".
30	type activityView interface {
31		ActivityTables() map[string]datatable.ActivityTable
32	}
33	
34	// migratedTables are the tables already on the activity column, by view.
35	var migratedTables = map[command.ViewType][]string{
36		command.ViewJobs: {"jobs/runs", "jobs/targets"},
37	}
38	
39	// pendingTable is a table that still has to move to the activity column.
40	type pendingTable struct {
41		Table string
42		View  command.ViewType
43		Story string
44	}
45	
46	// pendingTables may only shrink: each migration story removes its own entries.
47	var pendingTables = []pendingTable{
48		{"ws", command.ViewWorkspaces, "A-07"},
49		{"sec/inventory", command.ViewSecurity, "A-08"},
50		{"oci/images", command.ViewOCIResources, "A-09a"},
51		{"oci/registry-browser", command.ViewOCIResources, "A-09a"},
52		{"oci/networks", command.ViewOCIResources, "A-09b"},
53		{"oci/volumes", command.ViewOCIResources, "A-09b"},
54		{"oci/registries", command.ViewOCIResources, "A-09b"},
55		{"explorer/tree", command.ViewGitExplorer, "A-10a"},
56		{"explorer/clone-list", command.ViewGitExplorer, "A-10b"},
57		{"templates", command.ViewTemplates, "A-11"},
58		{"netdiag/ports", command.ViewNetdiag, "A-12"},
59		{"agent-usage/agents", command.ViewAgentUsage, "A-13"},
60		{"containers", command.ViewContainers, "A-14"},
61	}
62	
63	// maxPendingTables is the ceiling: adding an exception means raising both the
64	// list and this constant in the same diff, which is visible in review. Lower it
65	// with every migration.
66	const maxPendingTables = 13
67	
68	// exemptViews have no long-running operation to show per row (inventory:
69	// "sans objet" or out of the batch), each with its reason.
70	var exemptViews = map[command.ViewType]string{
71		command.ViewDashboard:     "no table with row operations; the dashboard is a summary",
72		command.ViewStatus:        "monitors are polled as a whole, not per-row operations",
73		command.ViewGitAuth:       "a form, no table",
74		command.ViewConfiguration: "a form of settings, no table of operations",
75		command.ViewAbout:         "static facts, no table",
76		command.ViewFiles:         "out of the batch, candidate for a later S story (the delete goes through the registry, no story covers it)",
77		command.ViewViewer:        "a document pane, no table",
78	}
79	
80	func pendingViews() map[command.ViewType][]pendingTable {
81		out := map[command.ViewType][]pendingTable{}
82		for _, p := range pendingTables {
83			out[p.View] = append(out[p.View], p)
84		}
85		return out
86	}
87	
88	func TestActivityGuardPendingListOnlyShrinks(t *testing.T) {
89		if got := len(pendingTables); got > maxPendingTables {
90			t.Errorf("pendingTables has %d entries, ceiling is %d: the list may only shrink (A-16 criterion 6)", got, maxPendingTables)
91		}
92		seen := map[string]bool{}
93		for _, p := range pendingTables {
94			if p.Story == "" {
95				t.Errorf("pending table %q names no story", p.Table)
96			}
97			if seen[p.Table] {
98				t.Errorf("pending table %q is listed twice", p.Table)
99			}
100			seen[p.Table] = true
101		}
102	}
103	
104	// builtView returns the view the router builds for vt, laid out at 60x30.
105	func builtView(t *testing.T, vt command.ViewType) tea.Model {
106		t.Helper()
107		a := routerAt(t, &bareView{}, 60, 30) // isolateHome, session-only secrets
108		a.createView(vt)
109		m := a.views[vt]
110		if m == nil {
111			t.Fatalf("view %q: the router did not build it", vt)
112		}
113		m, _ = m.Update(tea.WindowSizeMsg{Width: 60, Height: 30})
114		return m
115	}
116	
117	// classificationProblems says what is wrong with the classification of one
118	// view, empty when it is fine. It works per table: a view may be migrated for
119	// some tables and pending for others (A-09a/A-09b, A-10a/A-10b) as long as the
120	// two sets are disjoint; an exempt view is neither migrated nor pending.
121	func classificationProblems(vt command.ViewType, migrated map[command.ViewType][]string, pending []pendingTable, exempt map[command.ViewType]string) []string {
122		var problems []string
123		mig := migrated[vt]
124		var pend []string
125		for _, p := range pending {
126			if p.View == vt {
127				pend = append(pend, p.Table)
128			}
129		}
130		_, isExempt := exempt[vt]
131		switch {
132		case len(mig) == 0 && len(pend) == 0 && !isExempt:
133			problems = append(problems, "neither migrated, pending (with its story) nor exempt (with its reason)")
134		case isExempt && (len(mig) > 0 || len(pend) > 0):
135			problems = append(problems, "exempt and also migrated or pending")
136		}
137		for _, name := range pend {
138			if contains(mig, name) {
139				problems = append(problems, fmt.Sprintf("table %q is both migrated and pending", name))
140			}
141		}
142		return problems
143	}
144	
145	// staleExceptions lists the pending tables of a view that the view already
146	// reports: their exception must go.
147	func staleExceptions(vt command.ViewType, reported []string, pending []pendingTable) []string {
148		var stale []string
149		for _, p := range pending {
150			if p.View == vt && contains(reported, p.Table) {
151				stale = append(stale, p.Table)
152			}
153		}
154		return stale
155	}
156	
157	// Criterion 6: every view the router builds is migrated, pending or exempt.
158	func TestActivityGuardEveryViewIsClassified(t *testing.T) {
159		for _, name := range command.AllViewNames() {
160			vt := command.ViewType(name)
161			t.Run(name, func(t *testing.T) {
162				for _, p := range classificationProblems(vt, migratedTables, pendingTables, exemptViews) {
163					t.Errorf("view %q is %s: classify it in activity_guard_test.go", vt, p)
164				}
165			})
166		}
167	}
168	
169	// The logic itself, on a fictitious view that is partly migrated.
170	func TestActivityGuardClassificationLogic(t *testing.T) {
171		const v command.ViewType = "fiction"
172		pending := []pendingTable{{"fiction/b", v, "A-99"}}
173		tests := []struct {
174			name     string
175			migrated map[command.ViewType][]string
176			pending  []pendingTable
177			exempt   map[command.ViewType]string
178			problems int
179			stale    []string
180			reported []string
181		}{
182			{"partly migrated is fine", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
183			{"unclassified fails", nil, nil, nil, 1, nil, nil},
184			{"same table both ways fails", map[command.ViewType][]string{v: {"fiction/b"}}, pending, nil, 1, []string{"fiction/b"}, []string{"fiction/b"}},
185			{"exempt and pending fails", nil, pending, map[command.ViewType]string{v: "why"}, 1, nil, nil},
186			{"pending table not reported is not stale", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
187		}
188		for _, tt := range tests {
189			t.Run(tt.name, func(t *testing.T) {
190				if got := classificationProblems(v, tt.migrated, tt.pending, tt.exempt); len(got) != tt.problems {
191					t.Errorf("problems = %v, want %d", got, tt.problems)
192				}
193				if got := staleExceptions(v, tt.reported, tt.pending); !equalStrings(got, tt.stale) {
194					t.Errorf("stale = %v, want %v", got, tt.stale)
195				}
196			})
197		}
198	}
199	
200	func equalStrings(a, b []string) bool {
201		if len(a) != len(b) {
202			return false
203		}
204		for i := range a {
205			if a[i] != b[i] {
206				return false
207			}
208		}
209		return true
210	}
211	
212	// Criteria 1, 4 and the help half of 5, at runtime, on the views the router builds.
213	func TestActivityGuardMigratedViews(t *testing.T) {
214		legendTitle := indicator.Legend().Title
215		for vt, want := range migratedTables {
216			t.Run(string(vt), func(t *testing.T) {
217				m := builtView(t, vt)
218				av, ok := m.(activityView)
219				if !ok {
220					t.Fatalf("view %q is migrated but does not expose ActivityTables()", vt)
221				}
222				tables := av.ActivityTables()
223				for _, name := range want {
224					tb, ok := tables[name]
225					if !ok {
226						t.Errorf("view %q: table %q is migrated but ActivityTables() does not report it (reported: %v)", vt, name, sortedKeys(tables))
227						continue
228					}
229					checkColumnZero(t, vt, name, tb.Shapes())
230					// Criterion 4, Rule 116: the rendered extent, never the sum of columns.
231					if got, want := tb.RenderedWidth(), 60-2; got != want {
232						t.Errorf("view %q table %q: RenderedWidth() = %d at 60 columns, want %d (Rule 116)", vt, name, got, want)
233					}
234				}
235				for name := range tables {
236					if !contains(want, name) {
237						t.Errorf("view %q reports table %q, which migratedTables does not list", vt, name)
238					}
239				}
240				// Criterion 5, help half: the legend.
241				hp, ok := m.(help.Provider)
242				if !ok {
243					t.Fatalf("view %q has no help", vt)
244				}
245				found := false
246				for _, s := range hp.GetHelpContent().Sections {
247					found = found || s.Title == legendTitle
248				}
249				if !found {
250					t.Errorf("view %q: help has no %q section (indicator.Legend)", vt, legendTitle)
251				}
252			})
253		}
254	}
255	
256	// Criterion 6, other direction: a view that reports a table still listed as
257	// pending has migrated it; the exception must go. An exempt view must report
258	// none at all.
259	func TestActivityGuardNoStaleException(t *testing.T) {
260		for _, name := range command.AllViewNames() {
261			vt := command.ViewType(name)
262			_, isExempt := exemptViews[vt]
263			if !isExempt && len(pendingViews()[vt]) == 0 {
264				continue
265			}
266			t.Run(name, func(t *testing.T) {
267				av, ok := builtView(t, vt).(activityView)
268				if !ok {
269					return
270				}
271				if isExempt {
272					t.Errorf("view %q exposes ActivityTables() but is exempt: move it out of exemptViews", vt)
273				}
274				reported := sortedKeys(av.ActivityTables())
275				if stale := staleExceptions(vt, reported, pendingTables); len(stale) > 0 {
276					t.Errorf("view %q reports %v, still listed as pending: remove the exception", vt, stale)
277				}
278			})
279		}
280	}
281	
282	func checkColumnZero(t *testing.T, vt command.ViewType, table string, shapes []datatable.ColumnShape) {
283		t.Helper()
284		if len(shapes) == 0 {
285			t.Errorf("view %q table %q: no column reported", vt, table)
286			return
287		}
288		c := shapes[0]
289		var bad []string
290		if !c.Indicator {
291			bad = append(bad, "not an Indicator column")
292		}
293		if c.Title != "" {
294			bad = append(bad, fmt.Sprintf("title %q (want empty)", c.Title))
295		}
296		if c.Sizing != datatable.SizingFixed {
297			bad = append(bad, "not SizingFixed")
298		}
299		if c.MinWidth != datatable.IconColumnWidth {
300			bad = append(bad, fmt.Sprintf("MinWidth %d (want IconColumnWidth)", c.MinWidth))
301		}
302		if c.Less || c.Search {
303			bad = append(bad, "declares Less or Search")
304		}
305		if len(bad) > 0 {
306			t.Errorf("view %q table %q: column 0 is wrong: %s (A-16 criterion 1)", vt, table, strings.Join(bad, "; "))
307		}
308	}
309	
310	// migratedSourceDirs are scanned for the retired mechanisms (criterion 2b, and
311	// the hard-coded glyphs of 3). Only migrated views: pending ones still use them.
312	var migratedSourceDirs = []string{"ui/jobsview/"}
313	
314	// activityGlyphs are the runes of internal/ui/indicator; a view takes them from
315	// indicator.Glyph and never spells one.
316	const activityGlyphs = "●○◴⊗◐◕◉⊘⊖◌"
317	
318	// Criterion 2b: no AdvanceSpinner, no StatusColumn:, no frame field, no glyph
319	// literal in a migrated view. RenderedFrame (a method of the viewport frame) is allowed.
320	func TestActivityGuardMigratedSourcesUseNoRetiredMechanism(t *testing.T) {
321		scanned := 0
322		sourceFiles(t, func(rel string, fset *token.FileSet, file *ast.File) {
323			if !hasAnyPrefix(rel, migratedSourceDirs) {
324				return
325			}
326			scanned++
327			report := func(pos token.Pos, what string) {
328				t.Errorf("%s: %s in a migrated view (A-16 criterion 2b/3)", fset.Position(pos), what)
329			}
330			isFrame := func(name string) bool {
331				return name == "Frame" || name == "frame" || name == "SpinnerFrame"
332			}
333			ast.Inspect(file, func(n ast.Node) bool {
334				switch x := n.(type) {
335				case *ast.CallExpr:
336					if sel, ok := x.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "AdvanceSpinner" {
337						report(x.Pos(), "call to AdvanceSpinner")
338					}
339				case *ast.KeyValueExpr:
340					if id, ok := x.Key.(*ast.Ident); ok {
341						if id.Name == "StatusColumn" {
342							report(id.Pos(), "StatusColumn: key")
343						}
344						if isFrame(id.Name) {
345							report(id.Pos(), "frame field "+id.Name+": set")
346						}
347					}
348				case *ast.Field:
349					for _, id := range x.Names {
350						if isFrame(id.Name) {
351							report(id.Pos(), "frame field "+id.Name)
352						}
353					}
354				case *ast.SelectorExpr:
355					if isFrame(x.Sel.Name) {
356						report(x.Sel.Pos(), "frame selector ."+x.Sel.Name)
357					}
358				case *ast.BasicLit:
359					if x.Kind == token.STRING || x.Kind == token.CHAR {
360						s, err := strconv.Unquote(x.Value)
361						if x.Kind == token.CHAR {
362							var q rune
363							q, _, _, err = strconv.UnquoteChar(x.Value[1:len(x.Value)-1], '\'')
364							s = string(q)
365						}
366						if err == nil && strings.ContainsAny(s, activityGlyphs) {
367							report(x.Pos(), "activity glyph written as a literal "+x.Value+" (use indicator.Glyph)")
368						}
369					}
370				}
371				return true
372			})
373		})
374		if scanned == 0 {
375			t.Fatalf("no source file found under %v: the scan reads nothing", migratedSourceDirs)
376		}
377	}
378	
379	func hasAnyPrefix(s string, prefixes []string) bool {
380		for _, p := range prefixes {
381			if strings.HasPrefix(s, p) {
382				return true
383			}
384		}
385		return false
386	}
387	
388	func contains(list []string, s string) bool {
389		for _, x := range list {
390			if x == s {
391				return true
392			}
393		}
394		return false
395	}
396	
397	func sortedKeys(m map[string]datatable.ActivityTable) []string {
398		out := make([]string, 0, len(m))
399		for k := range m {
400			out = append(out, k)
401		}
402		sort.Strings(out)
403		return out
404	}
