117	// classificationProblems says what is wrong with the classification of one
118	// view, empty when it is fine. It works per table: a view may be migrated for
119	// some tables and pending for others (A-09a/A-09b, A-10a/A-10b) as long as the
120	// two sets are disjoint; an exempt view is neither migrated nor pending.
121	func classificationProblems(vt command.ViewType, migrated map[command.ViewType][]string, pending []pendingTable, exempt map[command.ViewType]string) []string {
122		var problems []string
123		mig := migrated[vt]
124		var pend []string
125		for _, p := range pending {
126			if p.View == vt {
127				pend = append(pend, p.Table)
128			}
129		}
130		_, isExempt := exempt[vt]
131		switch {
132		case len(mig) == 0 && len(pend) == 0 && !isExempt:
133			problems = append(problems, "neither migrated, pending (with its story) nor exempt (with its reason)")
134		case isExempt && (len(mig) > 0 || len(pend) > 0):
135			problems = append(problems, "exempt and also migrated or pending")
136		}
137		for _, name := range pend {
138			if contains(mig, name) {
