170	func TestActivityGuardClassificationLogic(t *testing.T) {
171		const v command.ViewType = "fiction"
172		pending := []pendingTable{{"fiction/b", v, "A-99"}}
173		tests := []struct {
174			name     string
175			migrated map[command.ViewType][]string
176			pending  []pendingTable
177			exempt   map[command.ViewType]string
178			problems int
