292		}
293		if c.Title != "" {
294			bad = append(bad, fmt.Sprintf("title %q (want empty)", c.Title))
295		}
296		if c.Sizing != datatable.SizingFixed {
297			bad = append(bad, "not SizingFixed")
298		}
299		if c.MinWidth != datatable.IconColumnWidth {
300			bad = append(bad, fmt.Sprintf("MinWidth %d (want IconColumnWidth)", c.MinWidth))
301		}
