310	// migratedSourceDirs are scanned for the retired mechanisms (criterion 2b, and
311	// the hard-coded glyphs of 3). Only migrated views: pending ones still use them.
312	var migratedSourceDirs = []string{"ui/jobsview/"}
313	
314	// activityGlyphs are the runes of internal/ui/indicator; a view takes them from
315	// indicator.Glyph and never spells one.
316	const activityGlyphs = "●○◴⊗◐◕◉⊘⊖◌"
