21	// sourceFiles parses every non-test Go file under ../ (internal/) and calls visit
22	// with its path relative to internal/, slash-separated.
23	func sourceFiles(t *testing.T, visit func(rel string, fset *token.FileSet, file *ast.File)) {
24		t.Helper()
25		root := ".."
26		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
27			if err != nil {
28				return err
29			}
30			if d.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
31				return nil
32			}
33			fset := token.NewFileSet()
34			file, perr := parser.ParseFile(fset, path, nil, 0)
35			if perr != nil {
36				t.Fatalf("parse %s: %v", path, perr)
37			}
38			rel, _ := filepath.Rel(root, path)
39			visit(filepath.ToSlash(rel), fset, file)
40			return nil
41		})
42		if err != nil {
43			t.Fatalf("walk %s: %v", root, err)
44		}
45	}
