55				if !ok {
56					return true
57				}
58				sel, ok := lit.Type.(*ast.SelectorExpr)
59				if ok && sel.Sel.Name == "FrameMsg" {
60					t.Errorf("%s: only internal/app builds a jobs.FrameMsg", fset.Position(lit.Pos()))
61				}
62				return true
63			})
64		})
