68	func TestTheRouterHasOneAnimationChain(t *testing.T) {
69		builders := map[string][]string{} // function -> positions
70		callers := map[string][]string{}
71		sourceFiles(t, func(rel string, fset *token.FileSet, file *ast.File) {
72			if !strings.HasPrefix(rel, "app/") || strings.Count(rel, "/") != 1 {
